import 'package:flutter/material.dart';import '../services/database_service.dart';
class MasterScreen extends StatefulWidget{const MasterScreen({super.key});@override State<MasterScreen>createState()=>_M();}
class _M extends State<MasterScreen>{final db=DB.i;String type='blok';List<Map<String,dynamic>> rows=[];String get table=>type;@override void initState(){super.initState();load();}Future<void>load()async{final r=await db.all(table);if(mounted)setState(()=>rows=r);}Future<void>add()async{final c=await showDialog<Map<String,dynamic>>(context:context,builder:(_)=>FormDialog(type:type));if(c!=null){await (await db.db).insert(table,c);load();}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Data Master')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:DropdownButtonFormField<String>(value:type,items:const[DropdownMenuItem(value:'blok',child:Text('Blok')),DropdownMenuItem(value:'mandor',child:Text('Mandor')),DropdownMenuItem(value:'grup',child:Text('Grup')),DropdownMenuItem(value:'pemanen',child:Text('Pemanen'))],onChanged:(v){setState(()=>type=v!);load();})),Expanded(child:RefreshIndicator(onRefresh:load,child:ListView.builder(itemCount:rows.length,itemBuilder:(_,i){final r=rows[i];return ListTile(leading:const Icon(Icons.person),title:Text('${r['kode']} • ${r['nama']}'),subtitle:Text(type=='blok'?'${r['luas_ha']} ha • ${r['jumlah_pokok']} pokok':type=='grup'?'Upah/orang Rp ${r['tarif_upah_per_orang']} • Premi/kg Rp ${r['tarif_premi_per_kg']}':'${r['no_hp']??''}'));}))) ]),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Tambah')));}
class FormDialog extends StatefulWidget{final String type;const FormDialog({super.key,required this.type});@override State<FormDialog>createState()=>_F();}
class _F extends State<FormDialog>{final code=TextEditingController(),name=TextEditingController(),hp=TextEditingController(),luas=TextEditingController(),tahun=TextEditingController(),pokok=TextEditingController(),tarif=TextEditingController(),premi=TextEditingController();@override Widget build(BuildContext c){final b=widget.type=='blok',g=widget.type=='grup';return AlertDialog(title:Text('Tambah ${widget.type}'),content:SingleChildScrollView(child:Column(children:[TextField(controller:code,decoration:const InputDecoration(labelText:'Kode')),TextField(controller:name,decoration:const InputDecoration(labelText:'Nama')),if(!b&&!g)TextField(controller:hp,decoration:const InputDecoration(labelText:'No. HP')),if(b)...[TextField(controller:luas,decoration:const InputDecoration(labelText:'Luas ha')),TextField(controller:tahun,decoration:const InputDecoration(labelText:'Tahun tanam')),TextField(controller:pokok,decoration:const InputDecoration(labelText:'Jumlah pokok'))],if(g)...[TextField(controller:tarif,decoration:const InputDecoration(labelText:'Upah/orang')),TextField(controller:premi,decoration:const InputDecoration(labelText:'Premi/kg'))]])),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Batal')),FilledButton(onPressed:(){final x=<String,dynamic>{'kode':code.text,'nama':name.text};if(b){x['kebun_id']=1;x['luas_ha']=double.tryParse(luas.text)??0;x['tahun_tanam']=int.tryParse(tahun.text);x['jumlah_pokok']=int.tryParse(pokok.text)??0;}if(g){x['tarif_upah_per_orang']=double.tryParse(tarif.text)??0;x['tarif_premi_per_kg']=double.tryParse(premi.text)??0;}if(!b&&!g)x['no_hp']=hp.text;if(widget.type=='pemanen')x['grup_id']=null;Navigator.pop(context,x);},child:const Text('Simpan'))]);}}
